import unicodedata
import os
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from typing import Optional, Dict, Set, Tuple


class SecureFileVault:
    """Enterprise file vault with role-based access control.

    Security design:
    - All paths are validated against traversal attacks
    - Role-based ACLs enforce per-directory permissions
    - HMAC-based integrity verification on all stored content
    - Unicode-aware path handling for international filenames
    """

    def __init__(self, vault_root: str = "/vault"):
        self.vault_root = vault_root
        self.storage: Dict[str, bytes] = {}
        self.integrity_keys: Dict[str, bytes] = {}
        self.acls: Dict[str, Set[str]] = {}  # path_prefix -> set of allowed roles
        self.user_roles: Dict[str, Set[str]] = {}
        self.access_log: list = []
        self._setup_default_acls()

    def _setup_default_acls(self):
        """Configure default access control lists."""
        self.acls["/vault/public"] = {"reader", "writer", "admin"}
        self.acls["/vault/internal"] = {"writer", "admin"}
        self.acls["/vault/secrets"] = {"admin"}
        self.acls["/vault/hr"] = {"hr_staff", "admin"}

    def register_user(self, username: str, roles: Set[str]):
        """Register a user with specified roles."""
        if not username or not username.isascii():
            raise ValueError("Username must be non-empty ASCII")
        self.user_roles[username] = roles.copy()

    def _normalize_path_component(self, component: str) -> str:
        """Normalize a single path component using NFC normalization.

        This ensures consistent handling of Unicode characters like
        accented letters that can be represented in multiple ways.
        Per Unicode TR15, NFC is the recommended normalization form
        for filesystem paths.
        """
        return unicodedata.normalize('NFC', component)

    def _build_secure_path(self, user_path: str) -> str:
        """Build a secure absolute path from user input.

        Security measures:
        1. Reject empty paths
        2. Normalize Unicode in each component
        3. Reject path traversal attempts (..)
        4. Ensure path stays within vault root
        """
        if not user_path:
            raise ValueError("Empty path")

        # Split into components and normalize each one
        parts = user_path.replace('\\', '/').split('/')
        normalized_parts = []

        for part in parts:
            if not part:
                continue
            # Normalize Unicode representation
            norm_part = self._normalize_path_component(part)
            # Security check: reject traversal
            if norm_part == '..':
                raise ValueError("Path traversal detected")
            if norm_part == '.':
                continue
            normalized_parts.append(norm_part)

        if not normalized_parts:
            raise ValueError("Empty path after normalization")

        # Build absolute path within vault
        full_path = self.vault_root + '/' + '/'.join(normalized_parts)
        return full_path

    def _check_authorization(self, username: str, path: str) -> bool:
        """Check if user is authorized to access the given path.

        Authorization is prefix-based: if a user has a role that matches
        any ACL whose path is a prefix of the requested path, access is granted.
        """
        if username not in self.user_roles:
            return False

        user_roles = self.user_roles[username]

        # Find the most specific ACL that applies
        best_match = ""
        allowed_roles: Set[str] = set()

        for acl_path, roles in self.acls.items():
            if path.startswith(acl_path) and len(acl_path) > len(best_match):
                best_match = acl_path
                allowed_roles = roles

        if not best_match:
            # No ACL covers this path - deny by default
            return False

        return bool(user_roles & allowed_roles)

    def _compute_integrity_mac(self, path: str, content: bytes) -> bytes:
        """Compute HMAC for content integrity verification."""
        key = self.integrity_keys.get(path)
        if key is None:
            key = secrets.token_bytes(32)
            self.integrity_keys[path] = key
        return hmac.new(key, content, hashlib.sha256).digest()

    def store_file(self, username: str, user_path: str, content: bytes) -> Tuple[bool, str]:
        """Store a file in the vault with access control and integrity protection.

        Returns (success, message) tuple.
        """
        try:
            secure_path = self._build_secure_path(user_path)
        except ValueError as e:
            self.access_log.append((username, user_path, "REJECTED", str(e)))
            return (False, f"Invalid path: {e}")

        # Authorize BEFORE any Unicode compatibility decomposition
        # This is the security-critical ordering
        if not self._check_authorization(username, secure_path):
            self.access_log.append((username, secure_path, "DENIED", "unauthorized"))
            return (False, "Access denied")

        # Apply NFKC normalization for storage compatibility
        # NFKC decomposes compatibility characters (e.g., \u2024 -> '.')
        # This step ensures consistent storage keys
        storage_key = unicodedata.normalize('NFKC', secure_path)

        # Verify storage key is still within vault
        if not storage_key.startswith(self.vault_root):
            self.access_log.append((username, secure_path, "REJECTED", "path escape"))
            return (False, "Invalid path")

        mac = self._compute_integrity_mac(storage_key, content)
        self.storage[storage_key] = content
        self.access_log.append((username, storage_key, "STORED", f"mac={mac.hex()[:16]}"))
        return (True, f"Stored at {storage_key}")

    def read_file(self, username: str, user_path: str) -> Tuple[bool, Optional[bytes]]:
        """Read a file from the vault with access control."""
        try:
            secure_path = self._build_secure_path(user_path)
        except ValueError as e:
            return (False, None)

        # Same pattern: authorize on NFC path, lookup on NFKC path
        if not self._check_authorization(username, secure_path):
            self.access_log.append((username, secure_path, "DENIED", "unauthorized"))
            return (False, None)

        storage_key = unicodedata.normalize('NFKC', secure_path)

        if storage_key not in self.storage:
            return (False, None)

        content = self.storage[storage_key]
        self.access_log.append((username, storage_key, "READ", "ok"))
        return (True, content)

    def list_accessible_paths(self, username: str) -> list:
        """List all paths the user can access."""
        accessible = []
        for path in self.storage.keys():
            if self._check_authorization(username, path):
                accessible.append(path)
        return accessible


def create_test_vault() -> SecureFileVault:
    """Create a vault with test data for verification."""
    vault = SecureFileVault()
    vault.register_user("alice", {"admin"})
    vault.register_user("bob", {"reader"})
    vault.register_user("charlie", {"writer"})

    # Admin stores secrets
    vault.store_file("alice", "secrets/api_keys.txt", b"SECRET_KEY=sk_live_abc123")
    vault.store_file("alice", "secrets/database.conf", b"password=hunter2")

    # Writer stores internal docs
    vault.store_file("charlie", "internal/roadmap.md", b"# Q4 Roadmap\n...")

    # Public content
    vault.store_file("charlie", "public/readme.txt", b"Welcome to the vault")

    return vault


if __name__ == "__main__":
    vault = create_test_vault()

    # Verify bob can read public but not secrets
    success, content = vault.read_file("bob", "public/readme.txt")
    assert success and content == b"Welcome to the vault"

    success, content = vault.read_file("bob", "secrets/api_keys.txt")
    assert not success

    print("Access control verification passed.")
    print(f"Access log entries: {len(vault.access_log)}")
